export const projectGeoCoordinates = (lon: number, lat: number): { x: number; y: number } => {
  const minLon = 16.469981;
  const maxLon = 32.893077;
  const minLat = -34.821954;
  const maxLat = -22.126452;
  const scaleX = 680.0 / (maxLon - minLon);
  const scaleY = 598.0 / (maxLat - minLat);
  const offsetX = 40.0;
  const offsetY = 31.0;

  const x = offsetX + (lon - minLon) * scaleX;
  const y = offsetY + (maxLat - lat) * scaleY;
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
};

