const pointInPoly = (x: number, y: number, poly: [number, number][]): boolean => {
  const n = poly.length;
  let inside = false;
  let p1 = poly[0];
  for (let j = 1; j <= n; j++) {
    const p2 = poly[j % n];
    if (y > Math.min(p1[1], p2[1])) {
      if (y <= Math.max(p1[1], p2[1])) {
        if (x <= Math.max(p1[0], p2[0])) {
          if (p1[1] !== p2[1]) {
            const xinters = (y - p1[1]) * (p2[0] - p1[0]) / (p2[1] - p1[1]) + p1[0];
            if (p1[0] === p2[0] || x <= xinters) {
              inside = !inside;
            }
          }
        }
      }
    }
    p1 = p2;
  }
  return inside;
};

export const isPointInSouthAfrica = (x: number, y: number): boolean => {
  return pointInPoly(x, y, OUTER_POLYGON_VERTICES) && !pointInPoly(x, y, LESOTHO_POLYGON_VERTICES);
};
